import{_ as c,r as n,o as p,c as d,e as l,a as t,s as a,d as e}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Мультисайт - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как переводить контент с помощью нескольких сайтов.","frontmatter":{"subtitle":"Узнайте, как переводить контент с помощью нескольких сайтов."},"headers":[{"level":2,"title":"Управление сайтами","slug":"управление-саитами","link":"#управление-саитами","children":[]},{"level":2,"title":"Компонент Site Picker","slug":"компонент-site-picker","link":"#компонент-site-picker","children":[]},{"level":2,"title":"Определение языка браузера","slug":"определение-языка-браузера","link":"#определение-языка-браузера","children":[]},{"level":2,"title":"Группы сайтов","slug":"группы-саитов","link":"#группы-саитов","children":[]},{"level":2,"title":"Ограничения ролей","slug":"ограничения-ролеи","link":"#ограничения-ролеи","children":[]},{"level":2,"title":"Функции мультисайта","slug":"функции-мультисаита","link":"#функции-мультисаита","children":[{"level":3,"title":"Отключение мультисайта","slug":"отключение-мультисаита","link":"#отключение-мультисаита","children":[]}]},{"level":2,"title":"PHP-интерфейс","slug":"php-интерфеис","link":"#php-интерфеис","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/resources/multisite.md","filePath":"3.x/ru/cms/resources/multisite.md"}'),h={name:"3.x/ru/cms/resources/multisite.md"};function u(g,s,k,v,m,f){const o=n("pre-heading"),r=n("post-heading"),i=n("VideoBlockLink");return p(),d("div",null,[l(o),s[0]||(s[0]=t("h1",null,"Мультисайт",-1)),l(r),l(i,{src:"https://www.youtube.com/watch?v=_kX7P3SEHg8",title:"Демонстрация мультисайта",description:"Это видео демонстрирует, как создавать мультиязычные сайты с помощью October CMS Multisite.",prompt:"Смотреть демонстрацию"}),s[1]||(s[1]=a(`<p>Функция мультисайта позволяет управлять несколькими веб-сайтами из одной установки October CMS и назначать контент в зависимости от доменного имени. Например, интернет-магазин с различными региональными поддоменами. Вы также можете использовать эту функцию для управления переводами локализованного сайта.</p><h2 id="управление-саитами"><a href="#управление-саитами" class="header-anchor">#</a> Управление сайтами</h2><p>Создавать сайты можно на странице <strong>Настройки → Управление сайтами</strong> в панели администрирования. Каждая установка включает основной сайт, который действует как сайт по умолчанию для каждого запроса.</p><p>Каждый сайт определяется следующей конфигурацией:</p><ul><li><strong>Включён</strong> — определяет доступность сайта на фронтенде и в панели администрирования.</li><li><strong>Название</strong> — указывает название сайта.</li><li><strong>Уникальный код</strong> — указывает уникальный код сайта для поиска через API.</li><li><strong>Тема</strong> — CMS-тема, используемая при активном сайте.</li><li><strong>Локаль</strong> — локаль приложения для этого сайта.</li><li><strong>Часовой пояс</strong> — часовой пояс для этого сайта.</li><li><strong>Пользовательский URL приложения</strong> — URL, используемый при активном сайте для таких вещей, как почтовые шаблоны или когда политика ссылок принудительно устанавливает URL.</li><li><strong>Использовать префикс маршрута CMS</strong> — определяет префикс для включения перед каждым маршрутом страницы. Может идентифицировать этот сайт при использовании общего имени хоста.</li><li><strong>Определить совпадающие имена хостов</strong> — сопоставляет сайт с определёнными именами хостов. Рекомендуется включить для продуктивных сайтов из соображений безопасности. Поддерживаются подстановочные значения, например: <code>*.mydomain.tld</code>.</li><li><strong>Отображать цвет для этого сайта</strong> — при включении отображает баннер в верхней части панели администрирования. Полезно для идентификации активного сайта или различения сред, например, красный для разработки, зелёный для стейджинга и без цвета для продакшена.</li></ul><p>При создании более одного сайта каждый из них можно выбрать в панели администрирования через выпадающее меню выбора сайта.</p><h2 id="компонент-site-picker"><a href="#компонент-site-picker" class="header-anchor">#</a> Компонент Site Picker</h2><p>Компонент <code>sitePicker</code> позволяет управлять ссылками на другие сайты. Лучшее место для его размещения — шаблон страницы или макета.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">sitePicker</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> availableSites <span class="token operator">=</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Обратитесь к <a href="./../components/sitepicker.html">статье о компоненте Site Picker</a>, чтобы узнать, как отображать URL сайтов и генерировать альтернативные ссылки на страницы.</p><h2 id="определение-языка-браузера"><a href="#определение-языка-браузера" class="header-anchor">#</a> Определение языка браузера</h2><p>October CMS настроен на автоматическое определение подходящего сайта на основе предпочтительного языка браузера при выполнении следующих условий:</p><ul><li>Все сайты в группе имеют установленный префикс</li><li>Нет других сайтов, соответствующих базовому URL</li></ul><p>Например, если основной сайт — <strong>English</strong> с префиксом маршрута <code>/en</code>, а другой сайт <strong>French</strong> имеет префикс <code>/fr</code>, то наблюдается следующее поведение.</p>`,14)),s[2]||(s[2]=t("div",{class:"table"},[t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"Базовый URL"),t("th",null,"Поведение")])]),t("tbody",null,[t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld/en",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld/en"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,[e("Отображает "),t("strong",null,"английский"),e(" сайт")])]),t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld/fr",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld/fr"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,[e("Отображает "),t("strong",null,"французский"),e(" сайт")])]),t("tr",null,[t("td",null,[t("a",{href:"https://yoursite.tld",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("https://yoursite.tld"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("td",null,"Перенаправление на основе языковых предпочтений")])])])],-1)),s[3]||(s[3]=a(`<p>Когда пользователь посещает базовый URL, его предпочтительный язык определяется автоматически и выполняется перенаправление на соответствующий сайт. Сопоставление сайта основано на значении его локали, и если совпадение не найдено, используется основной сайт.</p><div class="custom-block tip"><p>Вы можете изменить это поведение, используя значение <code>redirect_policy</code> в файле <strong>config/cms.php</strong>.</p></div><h2 id="группы-саитов"><a href="#группы-саитов" class="header-anchor">#</a> Группы сайтов</h2><p>В начальном состоянии мультисайт полезен для создания нескольких сайтов на одном языке или одного сайта на нескольких языках. Группировка сайтов позволяет расширить эту концепцию для создания нескольких сайтов с несколькими языками. Создавайте группы сайтов, перейдя в <strong>Настройки → Управление сайтами → Управление группами сайтов</strong>. После создания группы для каждого сайта появится поле выбора группы.</p><p>На практике каждая группа сайтов представляет веб-сайт, а определения сайтов в группе представляют сайт на альтернативном языке. Следующий пример показывает конфигурацию группированных сайтов для сайта о кошках и собаках с двумя языками для каждого.</p><div class="table"><table tabindex="0"><thead><tr><th>Группа сайтов</th><th>Название сайта</th></tr></thead><tbody><tr><td>Dogs</td><td>English</td></tr><tr><td>Dogs</td><td>French</td></tr><tr><td>Cats</td><td>English</td></tr><tr><td>Cats</td><td>French</td></tr></tbody></table></div><p>Группированные сайты реплицируют поля только внутри своей группы. Например, если <a href="./../tailor/introduction.html">чертёж Tailor</a> использует опцию <code>multisite: sync</code>, записи будут синхронизироваться только между сайтами одной группы.</p><h2 id="ограничения-ролеи"><a href="#ограничения-ролеи" class="header-anchor">#</a> Ограничения ролей</h2><p>Определения сайтов могут ограничивать видимость на основе роли администратора, что позволяет использовать выделенные роли для управления конкретными сайтами. Для включения ограничений ролей мультисайта:</p><ol><li>Перейдите в <strong>Управление сайтами</strong> и выберите определение сайта.</li><li>Установите флажок <strong>Определить роли администраторов</strong>.</li><li>Выберите роли, которым разрешён просмотр сайта.</li><li>Нажмите <strong>Сохранить</strong>.</li></ol><p>При включении сайт будет виден в панели администрирования только администраторам с указанными ролями. Например, для создания сайта, доступного только разработчикам, выберите роль <strong>Developer</strong> в поле.</p><h2 id="функции-мультисаита"><a href="#функции-мультисаита" class="header-anchor">#</a> Функции мультисайта</h2><p>Некоторые основные функции не поддерживают мультисайт по умолчанию, например конфигурация почты. Вы можете выборочно включить функции мультисайта с помощью файла <strong>config/multisite.php</strong> в разделе <code>features</code>. Следующие ключи функций доступны для использования с несколькими определениями сайтов.</p><div class="table"><table tabindex="0"><thead><tr><th>Функция</th><th>Описание</th></tr></thead><tbody><tr><td><code>cms_maintenance_setting</code></td><td>Настройки режима обслуживания уникальны для каждого сайта</td></tr><tr><td><code>backend_mail_setting</code></td><td>Настройки почты уникальны для каждого сайта</td></tr><tr><td><code>system_asset_combiner</code></td><td>Ключи кэша комбинатора ресурсов уникальны для сайта</td></tr></tbody></table></div><h3 id="отключение-мультисаита"><a href="#отключение-мультисаита" class="header-anchor">#</a> Отключение мультисайта</h3><p>Вы можете полностью отключить функции мультисайта, установив конфигурацию <code>enabled</code> в значение <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;enabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span>
</code></pre></div><h2 id="php-интерфеис"><a href="#php-интерфеис" class="header-anchor">#</a> PHP-интерфейс</h2><p><a href="./../../extend/services/site.html">Сервис сайта</a> включает глобальный фасад <code>Site</code>, предоставляющий инструменты для работы с мультисайтом. Например, следующий код находит модель в контексте сайта с ID <strong>2</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withContext</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Model</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Обратитесь к <a href="./../../extend/services/site.html">статье о сервисе Site</a>, чтобы узнать больше.</p><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4>`,22)),s[4]||(s[4]=t("div",{class:"custom-block also"},[t("ul",null,[t("li",null,[t("a",{href:"https://octobercms.com/features/multisite",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[e("Функции мультисайта"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),e(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),e(),t("span",{class:"sr-only"},"(opens new window)")])])]),t("li",null,[t("a",{href:"./../themes/localization.html"},"Локализация тем")]),t("li",null,[t("a",{href:"./../components/sitepicker.html"},"Компонент Site Picker")]),t("li",null,[t("a",{href:"./../../extend/database/traits.html"},"Трейт Multisite")]),t("li",null,[t("a",{href:"./../../extend/services/site.html"},"Сервис Site")])])],-1))])}const x=c(h,[["render",u]]);export{w as __pageData,x as default};
